from schema import Optional, Schema

GENERAL_CONFIG_SCHEMA = Schema(
    {
        Optional("publish"): {
            "reports": {
                Optional(str): {
                    Optional("preamble"): str,
                    Optional("afterword"): {
                        Optional("text"): str,
                        Optional("include_metadata"): bool,
                    },
                    Optional("documents"): {
                        Optional("title_prefix"): str,
                        Optional("preamble"): str,
                        Optional("include"): [str],
                        Optional("exclude"): [str],
                        Optional("table_mappings"): dict[str, str],
                        Optional("afterword"): str,
                    },
                    Optional("scores"): {Optional(str): tuple[float, float]},
                    Optional("include_non_normative"): bool,
                    Optional("figures"): {
                        "enable": bool,
                        Optional("data_rows_limit"): int,
                        Optional("data_sampling_rate"): int,
                    },
                },
            },
            Optional("path"): str,
        },
        Optional("dotstop"): {
            "dot_path": str,
            Optional("needs_path"): str,
            Optional("ignore_paths"): list[str],
        },
        Optional("artifacts"): {
            Optional("import"): {
                str: {
                    "artifact_path": str,
                    "import_path": str,
                    "namespace": str,
                }
            },
            "export": {
                "artifact_path": str,
                "project_name": str,
            },
        },
        Optional("scoring"): {
            Optional("dump_path"): str,
            Optional("run_validators"): bool,
            Optional("trusted_smes"): list[str],
        },
        Optional("plot"): {"output_path": str},
        "version": str,
    }
)
